const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const P=['Instagram','TikTok','Facebook','LinkedIn'];
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',campaigns:'m3 11 15-7v16L3 13z M7 15l2 6h4l-2-5 M21 8v8',content:'M5 3h10l4 4v14H5z M14 3v6h5 M8 13h8 M8 17h6',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 11h16 M8 15h2 M14 15h2',audiences:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-4 M16 3a4 4 0 0 1 0 8',assets:'M3 3h18v18H3z M3 17l6-6 5 5 3-3 4 4 M16 7h1',inquiries:'M3 4h18v14H8l-5 4z M7 8h10 M7 12h7',analytics:'M4 3v18h18 M8 17v-5 M13 17V7 M18 17V3',brand:'m12 3 9 5v8l-9 5-9-5V8z M8 12l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',ads:'M3 17 9 11l4 4 8-10 M15 5h6v6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',check:'m5 12 4 4L19 6',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',external:'M14 3h7v7 M21 3 11 13 M10 3H3v18h18v-7'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.content}"/></svg>`;
let state,boot,route='dashboard',contentTab='All posts',filters={},calendarView='Month',calendarDate=new Date(),currentPost,priorFocus,refreshTimer;
const can=(...roles)=>roles.some(r=>state?.user.roles.includes(r));
const name=id=>state?.users.find(u=>u.id===id)?.name||id||'Unassigned';
const lookup=(collection,id)=>state[collection].find(x=>x.id===id)?.name||'No '+collection.replace(/s$/,'');
const fmt=(date,zone=state?.settings.zone||'UTC',options={month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})=>date?new Intl.DateTimeFormat('en-US',{...options,timeZone:zone}).format(new Date(date)):'Not planned';
const badge=status=>`<span class="badge ${status==='In Review'?'review':status==='Changes Requested'?'revision':['Approved','Ready to Post'].includes(status)?'approved':status==='Posted'?'posted':''}">${esc(status)}</span>`;
const platform=p=>`<span class="platform"><span class="platform-icon ${p.toLowerCase()}">${({Instagram:'◎',TikTok:'♪',Facebook:'f',LinkedIn:'in'})[p]}</span>${p}</span>`;
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const toast=m=>{const el=$('#toast');el.textContent=m;el.style.display='block';clearTimeout(el.timer);el.timer=setTimeout(()=>el.style.display='none',6500);};
async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v;}
async function refresh(){state=await api('state');render();}
async function act(fn){try{await fn();}catch(e){toast(e.message);}}
const field=(label,key,value='',type='text',extra='')=>`<label class="field ${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea name="${key}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" name="${key}" value="${esc(value)}" ${extra}>`}</label>`;
const select=(label,key,value,options,extra='')=>`<label class="field">${label}<select name="${key}" ${extra}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;
const check=(label,key,value=false)=>`<label class="check-field"><input type="checkbox" name="${key}" ${value?'checked':''}>${label}</label>`;
const teamOptions=role=>state.users.filter(u=>!u.disabled&&u.roles.includes(role)).map(u=>[u.id,u.name]);
const readForm=form=>{const data=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(i=>data[i.name]=i.checked);return data;};
function openModal(title,body,wide=false){priorFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="ghost" data-close aria-label="Close dialog">✕</button></div><div class="modal-body">${body}</div></section></div>`;$('#modal-root [data-close]').onclick=closeModal;$('#modal-root input, #modal-root select, #modal-root button')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';currentPost=null;priorFocus?.focus();}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const a=$$('.modal button:not(:disabled),.modal input,.modal select,.modal textarea,.modal a[href]').filter(x=>x.offsetParent!==null);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus();}}});
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR MARKETING WORKSPACE</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="button-group">${actions}</div></div>`;}
const button=(label,action,primary=false)=>`<button data-action="${action}" class="${primary?'primary':''}">${icon(primary?'plus':'calendar',14)}${label}</button>`;
function nav(page){route=page;filters={};render();window.scrollTo(0,0);}
function reminders(){const now=Date.now();return state.posts.filter(p=>p.status!=='Posted' && ((p.deadline&&Date.parse(p.deadline)<now&&['In Review','Changes Requested'].includes(p.status)) || (p.planned&&Date.parse(p.planned)<now&&['Approved','Ready to Post'].includes(p.status))));}
function render(){
 const navItems=[['dashboard','Overview'],['campaigns','Campaigns'],['content','Content studio'],['calendar','Content calendar'],['audiences','Audience profiles'],['assets','Asset library'],['inquiries','Inquiries'],['analytics','Performance']];
 const pageNames={...Object.fromEntries(navItems),brand:'Brand profile',settings:'Settings & team',ads:'Advertising plans'};
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brandmark"><div class="mark">✧</div><div><strong>CSTC</strong><small>SOCIAL STUDIO</small></div></div><div class="workspace"><div class="mini-logo">CS</div><div><b>CSTC Safety</b><small>Team workspace</small></div><span class="muted">⌄</span></div><div class="nav-label">Workspace</div><nav class="nav">${navItems.map(([id,label])=>`<button data-nav="${id}" class="${route===id?'active':''}">${icon(id)}${label}${id==='content'?`<span class="count">${state.posts.length}</span>`:''}</button>`).join('')}</nav><div class="nav-label toggle-note">Manage</div><nav class="nav">${[['brand','Brand profile'],['ads','Advertising'],['settings','Settings & team']].map(([id,label])=>`<button data-nav="${id}" class="${route===id?'active':''}">${icon(id)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="manual-card"><b>◉ Manual publishing is on</b><p>Every post gets a human review.<br>You stay in control of what goes live.</p></div><div class="profile"><span class="avatar">${esc(initials(state.user.name))}</span><div><b>${esc(state.user.name)}</b><small>${esc(state.user.roles[0])}</small></div><button class="ghost small" data-action="logout" aria-label="Sign out">↪</button></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu ghost" data-action="menu" aria-label="Toggle navigation">☰</button><div class="breadcrumb">Workspace <span>/ &nbsp; ${pageNames[route]}</span></div><div class="top-actions"><a href="https://www.cstcsafety.com/" target="_blank" rel="noopener">Visit CSTC Safety ${icon('external',12)}</a>${state.demo?`<select id="identity" aria-label="Simulated identity">${state.users.filter(u=>!u.disabled).map(u=>`<option value="${u.id}" ${u.id===state.user.id?'selected':''}>Demo: ${esc(u.name)}</option>`).join('')}</select>`:''}<button class="ghost small" data-action="reminders" aria-label="Open reminders">${icon('bell',18)}${reminders().length||''}</button><span class="avatar">${esc(initials(state.user.name))}</span></div></header><div class="demo-ribbon"><span>${state.demo?'DEMONSTRATION • Identity switching is simulated. Sample campaigns are illustrative.':'AUTHENTICATED WORKSPACE • Role permissions enforced on the server.'}</span><span>Automatic publishing off &nbsp;·&nbsp; Advertising off</span></div><div class="page">${({dashboard:dashboard,campaigns:campaignsPage,content:contentPage,calendar:calendarPage,audiences:audiencesPage,assets:assetsPage,inquiries:inquiriesPage,analytics:analyticsPage,brand:brandPage,settings:settingsPage,ads:adsPage})[route]()}<footer class="footer"><span>© ${new Date().getFullYear()} CSTC Social Studio <span>·</span> Built for safer conversations.</span><span><i class="dot"></i> Review first. Publish with confidence.</span></footer></div></main></div>`;
 bind();
}
function dashboard(){const inReview=state.posts.filter(p=>p.status==='In Review'),ready=state.posts.filter(p=>['Approved','Ready to Post'].includes(p.status)),upcoming=state.posts.filter(p=>p.status!=='Posted').sort((a,b)=>(a.planned||'z').localeCompare(b.planned||'z'));
 return heading('Your studio, at a glance.','A little planning today. A stronger safety message tomorrow.',button('Open calendar','calendar')+button('Create content','new-post',true))+`<section class="hero"><div><div class="eyebrow">PLAN WITH PURPOSE. POST WITH CONFIDENCE.</div><h2>Good content. Safer communities.</h2><p>Bring your team, ideas, and platforms together. Let’s turn your safety expertise into conversations that matter.</p><button data-action="new-campaign">Create a campaign ${icon('arrow',14)}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="shield">✓</div><div class="art-star">✧</div><div class="art-star second">✦</div></div></section><div class="stats">${[[state.posts.filter(p=>p.status!=='Posted').length,'Planned posts','calendar','Across your content pipeline'],[inReview.length,'Awaiting review','content','Ready for a fresh pair of eyes'],[ready.length,'Ready for publishing','check','Approved · manual posting'],[state.leads.filter(l=>l.status==='New').length,'New inquiries','inquiries',can('Analyst','Publisher','Administrator')?'Manually entered leads':'Customer data restricted by role']].map(([n,label,ic,foot])=>`<div class="stat"><div class="stat-head">${label}<span class="stat-icon">${icon(ic,14)}</span></div><div class="stat-value">${n.toString().padStart(2,'0')}</div><div class="stat-foot">${foot}</div></div>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Coming up next</h2><p class="sub">Your next conversations, all in one place.</p></div><button class="text-link" data-action="calendar">View calendar ↗</button></div><div class="tabs"><button class="active">Upcoming posts <span class="muted">(${upcoming.length})</span></button><button data-action="content">All content</button></div>${upcoming.length?upcoming.slice(0,4).map(postRow).join(''):'<div class="empty">A clear calendar is a fresh start. Create your first draft.</div>'}</section><section class="panel"><div class="panel-head"><div><h2>Campaigns in motion</h2><p class="sub">Small steps toward bigger goals.</p></div><button class="text-link" data-action="campaigns">All campaigns ↗</button></div>${state.campaigns.slice(0,2).map(c=>{const ps=state.posts.filter(p=>p.campaign===c.id),posted=ps.filter(p=>p.status==='Posted').length;return `<div class="campaign-card"><div class="row"><div><h3>${esc(c.name)}</h3><p>${esc(c.offering)} &nbsp;·&nbsp; ${esc(lookup('audiences',c.audience))}</p></div>${badge(c.status||'Planning')}</div><progress class="progress" aria-label="Published campaign posts" value="${posted}" max="${ps.length||1}"></progress><div class="progress-caption"><span>${posted} of ${ps.length} posts published</span><span>${esc(c.start)} — ${esc(c.end)}</span></div></div>`;}).join('')||'<div class="empty">Create a campaign to give your content direction.</div>'}</section><section class="panel"><div class="panel-head"><h2>Make your next move</h2></div><div class="quick-links">${[['campaigns','Plan a campaign','new-campaign'],['content','Draft a post','new-post'],['content','Review content','review'],['inquiries','Add an inquiry','new-lead']].map(([i,t,a])=>`<button data-action="${a}">${icon(i)}${t}</button>`).join('')}</div></section></div><div class="dashboard-right"><section class="panel"><div class="panel-head"><div><h2>Needs your attention</h2><p class="sub">Keep your team moving forward.</p></div><span class="badge review">${inReview.length+reminders().length+state.posts.filter(p=>p.status==='Changes Requested').length}</span></div>${inReview.length?`<div class="task"><div class="task-dot">${icon('content',15)}</div><div><h3>${inReview.length} post${inReview.length===1?'':'s'} awaiting review</h3><p>A quick review keeps good ideas moving.</p><button class="small" data-action="review">Review content →</button></div></div>`:''}<div class="task"><div class="task-dot">${icon('bell',15)}</div><div><h3>${reminders().length} overdue reminders</h3><p>${state.posts.filter(p=>p.status==='Changes Requested').length} revision requests · ${state.leads.filter(l=>l.followUp&&l.followUp<new Date().toISOString().slice(0,10)&&!['Closed','Not a Fit'].includes(l.status)).length} overdue inquiry follow-ups</p><button class="small" data-action="reminders">Open reminders →</button></div></div><div class="task"><div class="task-dot">${icon('settings',15)}</div><div><h3>Confirm your destinations</h3><p>${P.filter(p=>!state.settings.accounts[p].verified).length} accounts need verification. Manual posting stays in your hands.</p><button class="text-link" data-action="settings">Manage connections ↗</button></div></div></section><section class="panel"><div class="panel-head"><h2>Your platform mix</h2><button class="text-link" data-action="analytics">View results ↗</button></div>${P.map(p=>`<div class="post-row">${platform(p)}<span class="post-info"></span><span class="muted help">${state.posts.filter(x=>x.platform===p).length} posts</span></div>`).join('')}<div class="empty">Performance is ready when you are.<br>Add your first manual results after posting.</div></section><div class="notice"><b>Built around human review</b><br>Planned dates are reminders. Nothing is published automatically, and no ads can spend.</div></div></div>`;
}
function postRow(p){return `<div class="post-row"><div class="date-tile">${p.planned?fmt(p.planned,p.zone,{month:'short'}).toUpperCase():'—'}<b>${p.planned?fmt(p.planned,p.zone,{day:'numeric'}):'—'}</b></div>${platform(p.platform).replace(p.platform+'</span>','</span>')}<div class="post-info"><h3>${esc(p.title)}</h3><p>${esc(lookup('campaigns',p.campaign))} · ${p.planned?esc(fmt(p.planned,p.zone)):'Not planned'}<br>${esc(p.zone||'UTC')} · Manual reminder</p></div>${badge(p.status)}<button class="ghost small" data-post="${p.id}" aria-label="Open ${esc(p.title)}">↗</button></div>`;}
function postFilters(){return `<div class="filters"><label class="search">Search content<input id="search-posts" value="${esc(filters.search||'')}" placeholder="Find a title or caption…"></label>${[['platform','Platform',P],['campaign','Campaign',state.campaigns.map(c=>[c.id,c.name])],['audience','Audience',state.audiences.map(a=>[a.id,a.name])],['status','Status',['Draft','In Review','Changes Requested','Approved','Ready to Post','Posted']],['author','Author',teamOptions('Author')],['reviewer','Reviewer',teamOptions('Reviewer')],['publisher','Publisher',teamOptions('Publisher')],['mode','Mode',['Manual','Automatic']]].map(([key,label,opts])=>select(label,'filter-'+key,filters[key]||'',[['','All'],...opts])).join('')}</div>`;}
function filteredPosts(){return state.posts.filter(p=>Object.entries(filters).every(([k,v])=>!v||(k==='search'?(p.title+' '+p.caption).toLowerCase().includes(v.toLowerCase()):p[k]===v)));}
function contentPage(){const ps=filteredPosts();return heading('Content studio','One idea. Four platforms. Every post gets its own review.',button('Repurpose an idea','repurpose')+button('Create content','new-post',true))+`<div class="notice">Template-based drafting · No AI service is connected. Confirm every offering and have qualified staff review technical safety guidance.</div>${postFilters()}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Content</th><th>Platform</th><th>Review status</th><th>Planned reminder</th><th>Team</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.title)}</strong><small>${esc(lookup('campaigns',p.campaign))}${p.illustrative?' · Illustrative':''}</small></td><td>${platform(p.platform)}</td><td>${badge(p.status)}<small>${state.checks[p.id].errors.length} blocking checks</small></td><td>${p.planned?esc(fmt(p.planned,p.zone)):'—'}<small>${esc(p.zone||'UTC')} · Manual</small></td><td>${esc(name(p.author))}<small>Review: ${esc(name(p.reviewer))}</small></td><td><button class="small" data-post="${p.id}">${p.status==='Ready to Post'?'Prepare to Post':'Open draft'} ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No posts match. Adjust filters or create a new draft.</td></tr>'}</tbody></table></div></section>`;}
function campaignsPage(){return heading('Campaigns with a purpose.','Connect your offering, your audience, and a clear next step.',button('New campaign','new-campaign',true))+`<div class="cards">${state.campaigns.map(c=>`<article class="card"><div class="row">${badge(c.status||'Planning')} ${c.illustrative?'<span class="badge">Illustrative</span>':''}</div><h2>${esc(c.name)}</h2><p>${esc(c.objective)}</p><div class="meta">${esc(c.start)} → ${esc(c.end)}</div><p><b>Offering:</b> ${esc(c.offering)}<br><b>Audience:</b> ${esc(lookup('audiences',c.audience))}<br><b>Success:</b> ${esc(c.metrics)}</p><div>${(c.platforms||[]).map(platform).join(' ')}</div><div class="button-group"><button class="small" data-edit-campaign="${c.id}">Edit plan</button><button class="small" data-draft-campaign="${c.id}">Create platform drafts ↗</button></div></article>`).join('')}</div><div class="notice toggle-note">Templates available: service spotlight, training promotion, educational series, frequently asked questions and company introduction. Confirm the relevant offering in each campaign.</div>`;}
function audiencesPage(){return heading('Know who you’re speaking to.','Reusable profiles that keep every message relevant.',button('New audience','new-audience',true))+`<div class="notice">Industry information comes from CSTC’s website. Decision-makers, audience needs and platform preferences below are inferred recommendations until validated by the team.</div><div class="cards">${state.audiences.map(a=>`<article class="card"><span class="badge">Audience recommendation</span><h2>${esc(a.name)}</h2><p><b>${esc(a.industry)}</b> · ${esc(a.role)}<br>${esc(a.geography)}</p><p>${esc(a.needs)}</p><h3>Where to reach them</h3><p>${esc(a.platforms)}</p><p><b>Relevant offerings:</b> ${esc(a.offerings)}</p><p><b>Themes:</b> ${esc(a.themes)}</p><p class="help">${esc(a.assumptions)}</p>${safeAnchor(a.source,'Source material')}<div class="button-group"><button class="small" data-edit-audience="${a.id}">Edit audience</button></div></article>`).join('')}</div>`;}
function safeAnchor(url,label){try{if(!['http:','https:'].includes(new URL(url).protocol))return '<span class="help">Source not configured</span>';return `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;}catch{return '<span class="help">Source not configured</span>';}}
function calendarPage(){const zone=state.settings.zone,ps=filteredPosts();const year=calendarDate.getUTCFullYear(),month=calendarDate.getUTCMonth();const title=calendarDate.toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'});let view='';if(calendarView==='Month'){const first=new Date(Date.UTC(year,month,1)),start=new Date(first);start.setUTCDate(1-first.getUTCDay());view=`<div class="calendar-scroll"><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setUTCDate(start.getUTCDate()+i);const key=d.toISOString().slice(0,10),events=ps.filter(p=>localDate(p.planned,zone)===key);return `<div class="calendar-day ${d.getUTCMonth()!==month?'off':''} ${key===localDate(new Date().toISOString(),zone)?'today':''}">${d.getUTCDate()}${events.map(p=>`<button class="calendar-event" data-post="${p.id}"><b>${esc(p.title)}</b>${esc(p.platform)} · ${esc(fmt(p.planned,zone,{hour:'numeric',minute:'2-digit'}))}<br>${esc(p.status)} · Manual reminder</button>`).join('')}</div>`;}).join('')}</div></div>`;}else{let list=ps.filter(p=>p.planned);if(calendarView==='Day')list=list.filter(p=>localDate(p.planned,zone)===calendarDate.toISOString().slice(0,10));if(calendarView==='Week'){const start=new Date(calendarDate);start.setUTCHours(0,0,0,0);const end=new Date(start);end.setUTCDate(start.getUTCDate()+7);list=list.filter(p=>localDate(p.planned,zone)>=start.toISOString().slice(0,10)&&localDate(p.planned,zone)<end.toISOString().slice(0,10));}view=list.sort((a,b)=>a.planned.localeCompare(b.planned)).map(postRow).join('')||'<div class="empty">No reminders in this view. Open a draft to set its planned date.</div>';}
 return heading('Your shared content calendar.','Plan together. Review on time. Publish with intention.',button('Create content','new-post',true))+`<div class="notice">${icon('calendar',13)} Manual mode: all dates create in-app reminders only. Time zone: <b>${esc(zone)}</b>. Edit any entry to reschedule with an explicit UTC offset.</div>${postFilters()}<section class="panel"><div class="calendar-head"><div class="button-group"><button class="small" data-cal="prev" aria-label="Previous period">‹</button><h2>${title}</h2><button class="small" data-cal="next" aria-label="Next period">›</button><button class="small" data-cal="today">Today</button></div><div class="button-group">${['Month','Week','Day','List'].map(v=>`<button class="small ${calendarView===v?'primary':''}" data-view="${v}">${v}</button>`).join('')}</div></div>${view}</section>`;
}
function localDate(date,zone){if(!date)return '';return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(date));}
function assetsPage(){return heading('Good assets. Ready to reuse.','A shared home for creative, accessibility text, and recorded permissions.',button('Upload asset','upload',true))+`<div class="notice">Media is stored on the server. Upload PNG, JPEG, WebP or MP4 up to 10 MB. A reviewer must approve permissions before an asset can be used in a ready-to-post draft.</div><div class="cards">${state.assets.map(a=>`<article class="card">${a.mime.startsWith('image/')?`<img class="asset-thumbnail" src="/media/${a.file}" alt="${esc(a.alt)}">`:`<video class="asset-thumbnail" src="/media/${a.file}" controls></video>`}${badge(a.status)}<h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="meta">${esc(name(a.owner))} · ${esc(fmt(a.uploadedAt))}<br>Tags: ${esc(a.tags||'None')}</div><p><b>Permission:</b> ${esc(a.rights||'Missing')}<br><b>Expires:</b> ${esc(a.expires||'Not specified')}${a.restricted?'<br>Restricted — blocked from use':''}</p><div class="button-group"><a class="link-button" href="/media/${a.file}" download>Download</a>${a.status!=='Approved'&&can('Reviewer','Administrator')?`<button class="small" data-edit-asset="${a.id}">Edit permissions</button><button class="small" data-approve-asset="${a.id}">Approve rights</button>`:''}</div></article>`).join('')||'<div class="card empty">Your asset library is ready.<br>Upload your team’s first approved creative.</div>'}</div>`;}
function inquiriesPage(){if(!can('Analyst','Publisher','Administrator'))return heading('Inquiries','Customer information is limited to analysts, publishers, and administrators.')+'<div class="notice">Your role does not have access to inquiry records.</div>';return heading('Turn conversations into connections.','Log inquiries, assign follow-ups, and keep the next step clear.',button('Add inquiry','new-lead',true))+`<div class="notice">Manual entry only. Calls, emails, DMs and website forms are not automatically captured.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Contact / organization</th><th>Channel</th><th>Offering</th><th>Status</th><th>Follow-up</th><th></th></tr></thead><tbody>${state.leads.map(l=>`<tr><td><strong>${esc(l.contact)}</strong><small>Manual entry · ${esc(l.date)}</small></td><td>${esc(l.channel)}<small>${esc(lookup('campaigns',l.campaign))}</small></td><td>${esc(l.offering)}</td><td>${badge(l.status)}</td><td>${esc(l.followUp||'Not assigned')}<small>${esc(name(l.assignee))}${l.followUp<new Date().toISOString().slice(0,10)&&!['Closed','Not a Fit'].includes(l.status)?' · Overdue':''}</small></td><td><button class="small" data-edit-lead="${l.id}">Open inquiry</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No inquiries recorded. Add a conversation when it happens.</td></tr>'}</tbody></table></div></section>`;}
function analyticsPage(){const ms=state.metrics.filter(m=>(!filters.platform||m.platform===filters.platform)&&(!filters.campaign||m.campaign===filters.campaign)&&(!filters.theme||m.theme===filters.theme)&&(!filters.from||m.date>=filters.from)&&(!filters.to||m.date<=filters.to));const sum=k=>{const vals=ms.filter(m=>m[k]!==''&&m[k]!==null&&m[k]!==undefined);return vals.length?vals.reduce((a,m)=>a+Number(m[k]),0):null;};const display=v=>v===null?'—':v.toLocaleString();return heading('See what starts a conversation.','Real results begin with real data. Add results from each platform.',button('Export CSV','export')+(can('Analyst','Administrator')?button('Record results','new-metric',true):''))+`<div class="notice">Manual results only · Missing values display as —, distinct from zero. Platform definitions vary; compare each platform’s results in context.</div><div class="filters">${select('Platform','filter-platform',filters.platform||'',[['','All'],...P])}${select('Campaign','filter-campaign',filters.campaign||'',[['','All'],...state.campaigns.map(c=>[c.id,c.name])])}${select('Theme','filter-theme',filters.theme||'',[['','All'],...[...new Set(state.metrics.map(m=>m.theme).filter(Boolean))]])}${field('From','filter-from',filters.from||'','date')}${field('Through','filter-to',filters.to||'','date')}</div><div class="metric-row">${[['Recorded inquiries',sum('inquiries')],['Qualified leads',sum('qualified')],['Platform result records',ms.length]].map(([l,v])=>`<div class="metric-box"><small>${l}</small><strong>${display(v)}</strong></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Results by platform and campaign</h2></div><div class="table-wrap"><table><thead><tr><th>Platform / campaign</th><th>Reach / impressions</th><th>Views</th><th>Interactions</th><th>Clicks</th><th>Engagement rate</th><th>Source</th></tr></thead><tbody>${ms.map(m=>{const keys=['likes','comments','shares','saves'],valid=keys.every(k=>m[k]!==''&&m[k]!==null&&m[k]!==undefined),eng=valid?keys.reduce((a,k)=>a+Number(m[k]),0):null,rate=eng!==null&&Number(m.impressions)>0?(eng/Number(m.impressions)*100).toFixed(2)+'%':'—';const val=k=>m[k]===''||m[k]===null||m[k]===undefined?'—':esc(m[k]);return `<tr><td>${platform(m.platform)}<small>${esc(lookup('campaigns',m.campaign))} · ${esc(m.date)}<br>${esc(m.theme||'No theme')}</small></td><td>${val('reach')} / ${val('impressions')}</td><td>${val('views')}</td><td>${display(eng)}</td><td>${val('clicks')}</td><td>${rate}</td><td>Manual entry<small>${esc(fmt(m.updatedAt))}</small></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">No performance data yet. No sample results are presented as actual results.</td></tr>'}</tbody></table></div></section><div class="notice"><b>Definitions & calculations</b><br>Reach: unique accounts reported by the platform. Impressions: reported displays. Views: platform-defined video views. Interactions: likes + comments + shares + saves; all four values are required. Engagement rate = interactions ÷ impressions × 100, when impressions are greater than zero. Inquiries and qualified leads are manually attributed. Advertising spend and cost per result remain unavailable while advertising is disabled. A UTM link alone does not establish a conversion.</div>`;}
function brandPage(){const b=state.brand;return heading('A consistent voice. A trusted source.','Keep the company facts behind your content accurate and easy to find.',can('Administrator')?button('Edit brand profile','edit-brand',true):'')+`<div class="notice">Website facts reviewed November 24, 2026. Studio colors and the text logo are provisional. Official logo, brand colors, social profiles and messaging destinations still need verification.</div><div class="split"><section class="panel"><div class="panel-head"><h2>CSTC Safety brand profile</h2></div><div class="modal-body">${b.logo?`<img class="asset-thumbnail" src="${esc(b.logo)}" alt="${esc(b.name)} logo">`:''}<h3>${esc(b.name)}</h3><p class="help">${esc(b.description)}</p><div class="section-title">Offerings & geography</div><p class="help">${esc(b.offerings)}<br>${esc(b.geography)}</p><div class="section-title">Recommended writing style</div><p class="help">${esc(b.style)}</p><p class="help">${esc(b.colors)}</p><div class="section-title">Contact destinations</div><div class="button-group"><a class="link-button" href="https://www.cstcsafety.com/" target="_blank" rel="noopener">Visit CSTC Safety ↗</a>${b.contactsVerified&&/^\+\d+$/.test(b.phone)?`<a class="link-button" href="tel:${esc(b.phone)}">Call Us</a>`:''}${b.contactsVerified&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(b.email)?`<a class="link-button" href="mailto:${esc(b.email)}">Email Us</a>`:''}${b.dm&&b.dmVerified?safeAnchor(b.dm,'DM Us'):'<span class="badge">DM: needs verification</span>'}</div><p class="help">${esc(b.phone)} · ${esc(b.email)}<br>Contact verification: ${esc(b.contactVerifiedAt)} · ${safeAnchor(b.contactSource,'Source')}</p></div></section><section class="panel"><div class="panel-head"><h2>Fact & source register</h2></div><div class="modal-body source-list">${b.facts.map(f=>`<div><h3>${esc(f.label)}</h3><p>${esc(f.value)}</p>${badge(f.verified?'Verified website fact':'Needs verification')} <span class="help">${esc(f.verifiedAt)}</span><br>${safeAnchor(f.source,'View source')}</div>`).join('')}</div></section></div>`;}
function settingsPage(){return heading('Your workspace, your controls.','Publishing permissions, team access, and platform requirements.')+`<div class="notice">${state.demo?'Demo identity switching is a simulation, not production authentication.':'Team members sign in with server-verified passwords and expiring HttpOnly sessions.'} ${esc(state.settings.notifications)}</div><div class="split"><section class="panel"><div class="panel-head"><h2>Publishing & connections</h2></div><div class="modal-body"><div class="setting-row"><div><h3>Manual publishing</h3><p class="help">Review → prepare → post on the platform → record the live link.</p></div><span class="badge approved">Default</span></div><div class="setting-row"><div><h3>Automatic publishing</h3><p class="help">No official API adapters, OAuth credentials or production approvals configured.</p></div><span class="disabled-pill">Disabled</span></div><div class="setting-row"><div><h3>Paid advertising</h3><p class="help">Planning and export only. Separate budget authorization required for future spending.</p></div><span class="disabled-pill">Disabled</span></div><div class="button-group"><button data-action="pause" class="danger">Pause All Automatic Publishing</button>${state.demo?'<button data-action="simulation">Explore queue simulation</button>':''}</div><p class="help">${state.settings.paused?'Paused. No submissions can start.':'Automatic publishing is unavailable.'} No queue worker is installed; scheduling and retry operations cannot run.</p><div class="section-title">Manual destination accounts</div>${P.map(p=>`<div class="setting-row"><div>${platform(p)}<p class="help">${state.settings.accounts[p].verified?'Team-verified manual destination':'Not configured'} · API disconnected</p></div>${badge(state.settings.accounts[p].verified?'Verified':'Needs setup')}</div>`).join('')}${can('Administrator')?'<button class="primary" data-action="configure">Configure workspace</button>':''}</div></section><section class="panel"><div class="panel-head"><h2>Team & permissions</h2>${can('Administrator')?'<button class="small" data-action="new-user">Add teammate</button>':''}</div><div class="modal-body">${state.users.map(u=>`<div class="post-row"><span class="avatar">${esc(initials(u.name))}</span><div class="post-info"><h3>${esc(u.name)}</h3><p>${esc(u.roles.join(' · '))}${u.qualified?'<br>Qualified technical reviewer':''}${u.disabled?'<br>Access disabled':''}</p></div>${can('Administrator')?`<button class="small" data-edit-user="${u.id}">Edit</button>`:''}</div>`).join('')}<p class="help">Authors cannot approve their own work. Approval requires the assigned reviewer. Analysts, publishers and administrators can access inquiry information. Authors can create content; publishers can prepare approved posts.</p><div class="section-title">Official integration setup references</div>${P.map(p=>`<p class="help">${platform(p)}<br>${safeAnchor(state.settings.requirements[p].source,'Official documentation')}<br>Requirements review: ${esc(state.settings.requirements[p].reviewedAt||'Pending')}<br>Eligibility, scopes, app review, supported formats, token expiry and reconnection steps must be confirmed during adapter implementation.</p>`).join('')}</div></section></div>${can('Administrator')?`<section class="panel"><div class="panel-head"><h2>Workspace audit history</h2></div><div class="modal-body history">${state.audit.slice(-30).reverse().map(a=>`<p>${esc(fmt(a.at))} · ${esc(name(a.actor))}<br>${esc(a.action)} · ${esc(a.record)}</p>`).join('')||'Actions will appear here as your team works.'}</div></section>`:''}`;}
function adsPage(){return heading('Plan before you promote.','A separate workspace for advertising plans. Organic approval never authorizes spend.',button('Export plans','export-ads')+button('Create ad plan','new-ad',true))+`<div class="notice warning"><b>Planning only · Paid advertising is disabled.</b> No live ad APIs, ad accounts or budget authorization service are connected. Nothing here launches an ad or incurs a charge. Platform reporting delays can affect spending controls; app-side limits cannot guarantee an immediate platform stop.</div><div class="cards">${state.adPlans.map(a=>`<article class="card"><span class="badge">Planning only</span><h2>${esc(a.name)}</h2><p>${esc(a.objective)}</p>${platform(a.platform)}<p><b>Audience:</b> ${esc(a.audience)}<br><b>Geography:</b> ${esc(a.geography)}<br><b>Proposed budget:</b> ${esc(a.currency)} ${esc(a.budget)} ${esc(a.budgetType)}<br><b>Dates:</b> ${esc(a.start)} → ${esc(a.end)}<br><b>Budget approver:</b> ${esc(name(a.approver))}</p><button class="small" data-ad-summary="${a.id}">Review proposed authorization</button></article>`).join('')||'<article class="card empty">Create an advertising plan to prepare your objective, audience, creative and proposed budget.<br>No spending actions are available.</article>'}</div>`;}
function bind(){
 $$('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));
 $$('[data-action]').forEach(b=>b.onclick=()=>act(()=>action(b.dataset.action)));
 $$('[data-post]').forEach(b=>b.onclick=()=>postEditor(b.dataset.post));
 $$('[name^="filter-"]').forEach(s=>s.onchange=()=>{filters[s.name.slice(7)]=s.value;render();});
 if($('#search-posts'))$('#search-posts').onchange=e=>{filters.search=e.target.value;render();};
 if($('#identity'))$('#identity').onchange=e=>act(async()=>{await api('session','POST',{id:e.target.value});await refresh();toast('Demo identity switched. This is a simulation.');});
 $$('[data-edit-user]').forEach(b=>b.onclick=()=>userForm(b.dataset.editUser));
 $$('[data-edit-campaign]').forEach(b=>b.onclick=()=>campaignForm(b.dataset.editCampaign));
 $$('[data-draft-campaign]').forEach(b=>b.onclick=()=>repurpose(b.dataset.draftCampaign));
 $$('[data-edit-audience]').forEach(b=>b.onclick=()=>audienceForm(b.dataset.editAudience));
 $$('[data-edit-lead]').forEach(b=>b.onclick=()=>leadForm(b.dataset.editLead));
 $$('[data-edit-asset]').forEach(b=>b.onclick=()=>assetForm(b.dataset.editAsset));
 $$('[data-approve-asset]').forEach(b=>b.onclick=()=>act(async()=>{await api('assets/'+b.dataset.approveAsset+'/approve','POST',{});await refresh();toast('Asset permission approved.');}));
 $$('[data-view]').forEach(b=>b.onclick=()=>{calendarView=b.dataset.view;render();});
 $$('[data-cal]').forEach(b=>b.onclick=()=>{const d=b.dataset.cal;if(d==='today')calendarDate=new Date();else if(calendarView==='Month'){calendarDate.setUTCDate(1);calendarDate.setUTCMonth(calendarDate.getUTCMonth()+(d==='next'?1:-1));}else calendarDate.setUTCDate(calendarDate.getUTCDate()+(d==='next'?1:-1)*(calendarView==='Week'?7:1));render();});
 $$('[data-ad-summary]').forEach(b=>b.onclick=()=>{const a=state.adPlans.find(a=>a.id===b.dataset.adSummary);openModal('Proposed advertising authorization',`<div class="notice warning">Not authorized. Planning only. No launch or spending controls are available.</div><p class="help"><b>Account:</b> ${esc(a.account||'Not connected')}<br><b>Platform:</b> ${esc(a.platform)}<br><b>Audience:</b> ${esc(a.audience)}<br><b>Geography:</b> ${esc(a.geography)}<br><b>Creative:</b> ${esc(a.creative)}<br><b>Dates:</b> ${esc(a.start)} → ${esc(a.end)}<br><b>Currency / proposed limit:</b> ${esc(a.currency)} ${esc(a.budget)} ${esc(a.budgetType)}<br><b>Spend alert threshold:</b> ${esc(a.alert)}<br><b>Reviewer:</b> ${esc(name(a.reviewer))}<br><b>Budget approver:</b> ${esc(name(a.approver))}<br><b>Landing page:</b> ${safeAnchor(a.landing,'Open landing page')}<br><b>Success metric:</b> ${esc(a.metrics)}</p><div class="notice">External blocker: implement official ad API connection, server-enforced budget approval, idempotent launch, reconciliation and platform-confirmed pause before spending can be enabled.</div>`);});
}
async function action(a){if(['calendar','campaigns','content','settings','analytics'].includes(a))return nav(a);if(a==='menu')return $('.sidebar').classList.toggle('open');if(a==='new-post')return postEditor();if(a==='new-campaign')return campaignForm();if(a==='new-audience')return audienceForm();if(a==='new-lead')return leadForm();if(a==='new-metric')return metricForm();if(a==='new-ad')return adForm();if(a==='upload')return uploadForm();if(a==='edit-brand')return brandForm();if(a==='configure')return settingsForm();if(a==='repurpose')return repurpose();if(a==='review'){route='content';filters={status:'In Review'};return render();}if(a==='new-user')return userForm();if(a==='simulation')return simulationModal();if(a==='export')return exportCsv(state.metrics,'cstc-manual-results.csv');if(a==='export-ads')return exportCsv(state.adPlans,'cstc-advertising-plans-NOT-AUTHORIZED.csv');if(a==='pause'){await api('settings','PUT',{paused:true});await refresh();return toast('All automatic publishing paused. No live integration is configured.');}if(a==='logout'){await api('logout','POST',{});return start();}if(a==='reminders')return openModal('Your in-app reminders',`<div class="notice">${esc(state.settings.notifications)} Dates are reminders only; they never trigger publication.</div>${reminders().map(p=>`<div class="task"><div><h3>${esc(p.title)}</h3><p>${esc(p.status)} · Review: ${esc(fmt(p.deadline,p.zone))}<br>Assigned: ${esc(name(p.status==='In Review'?p.reviewer:p.publisher))}</p></div></div>`).join('')||'<p class="help">No overdue post reminders.</p>'}${state.leads.filter(l=>l.followUp&&l.followUp<new Date().toISOString().slice(0,10)&&!['Closed','Not a Fit'].includes(l.status)).map(l=>`<div class="task"><div><h3>Inquiry follow-up: ${esc(l.contact)}</h3><p>Due ${esc(l.followUp)} · ${esc(name(l.assignee))}</p></div></div>`).join('')}`);}
function simpleForm(title,html,onSave,wide=false){openModal(title,`<form id="entity-form"><div class="form-grid">${html}</div><div class="form-actions"><button type="button" data-cancel>Cancel</button><button class="primary" type="submit">Save changes</button></div></form>`,wide);$('[data-cancel]').onclick=closeModal;$('#entity-form').onsubmit=e=>{e.preventDefault();act(async()=>{await onSave(readForm(e.target));closeModal();await refresh();toast('Saved to the shared workspace.');});};}
function campaignForm(id){const c=state.campaigns.find(c=>c.id===id)||{author:state.user.id,reviewer:teamOptions('Reviewer')[0]?.[0],publisher:teamOptions('Publisher')[0]?.[0]};simpleForm(id?'Edit campaign':'Plan a campaign',field('Campaign name','name',c.name,'text','required')+select('Template','template',c.template||'Service spotlight',['Service spotlight','Training promotion','Educational series','Frequently asked questions','Company introduction'])+field('Objective','objective',c.objective)+field('Relevant company offering','offering',c.offering,'text','required')+select('Target audience','audience',c.audience,state.audiences.map(a=>[a.id,a.name]))+select('Status','status',c.status||'Planning',['Planning','Active','Completed'])+field('Start date','start',c.start||'','date','required')+field('End date','end',c.end||'','date','required')+select('Author','author',c.author,teamOptions('Author'))+select('Reviewer','reviewer',c.reviewer,teamOptions('Reviewer'))+select('Publisher','publisher',c.publisher,teamOptions('Publisher'))+select('Primary CTA','cta',c.cta||'Website',['Website','Call','Email','DM','Bio'])+field('Content themes','themes',c.themes,'textarea')+field('Success metrics','metrics',c.metrics)+field('UTM campaign name (no personal information)','utmCampaign',c.utmCampaign)+`<div class="field full">Platforms<div class="button-group">${P.map(p=>check(p,'platform-'+p,(c.platforms||P).includes(p))).join('')}</div></div><div class="field full">${check('The team confirms that CSTC offers the selected offering and this template is relevant.','offeringConfirmed',c.offeringConfirmed)}</div>`,async d=>{d.platforms=P.filter(p=>d['platform-'+p]);if(d.end<d.start)throw Error('End date must follow start date.');await api('campaigns'+(id?'/'+id:''),id?'PUT':'POST',d);});}
function audienceForm(id){const a=state.audiences.find(a=>a.id===id)||{};simpleForm('Audience profile',field('Profile name','name',a.name,'text','required')+field('Industry','industry',a.industry)+field('Decision-maker roles','role',a.role)+field('Geographic area','geography',a.geography)+field('Needs & common questions','needs',a.needs,'textarea')+field('Relevant verified offerings','offerings',a.offerings)+field('Content themes','themes',a.themes)+field('Recommended platforms & reasons','platforms',a.platforms,'textarea')+field('Source material URL','source',a.source,'url')+field('Assumptions / validation needed','assumptions',a.assumptions,'textarea'),d=>api('audiences'+(id?'/'+id:''),id?'PUT':'POST',d));}
function leadForm(id){const l=state.leads.find(l=>l.id===id)||{};simpleForm('Manually record an inquiry',`<div class="notice full">Collect only the contact or organization information your team needs. This record is manually entered.</div>`+field('Contact or organization','contact',l.contact,'text','required')+select('Channel','channel',l.channel||'Call',['Call','Email','DM','Website form','Campaign link','Other'])+field('Inquiry date','date',l.date||new Date().toISOString().slice(0,10),'date','required')+select('Status','status',l.status||'New',['New','Contacted','Qualified','Closed','Not a Fit'])+select('Related campaign','campaign',l.campaign,[['','Unknown'],...state.campaigns.map(c=>[c.id,c.name])])+select('Related post','post',l.post,[['','Unknown'],...state.posts.map(p=>[p.id,p.title+' · '+p.platform])])+field('Requested offering','offering',l.offering)+select('Assigned teammate','assignee',l.assignee,state.users.filter(u=>u.roles.some(r=>['Analyst','Publisher','Administrator'].includes(r))).map(u=>[u.id,u.name]))+field('Follow-up date','followUp',l.followUp||'','date')+field('Notes (avoid unnecessary personal information)','notes',l.notes,'textarea'),d=>api('leads'+(id?'/'+id:''),id?'PUT':'POST',{...d,source:'Manual entry'}));}
function metricForm(){simpleForm('Record manual platform results',select('Platform','platform','LinkedIn',P)+select('Campaign','campaign','',[['','Unattributed'],...state.campaigns.map(c=>[c.id,c.name])])+select('Post','post','',[['','Unattributed'],...state.posts.map(p=>[p.id,p.title+' · '+p.platform])])+field('Measurement date','date',new Date().toISOString().slice(0,10),'date','required')+field('Content theme','theme')+`<div class="notice full">Leave unavailable metrics blank. Enter 0 only when the platform reports zero. Use the same reporting period for each value.</div>`+['reach','impressions','views','likes','comments','shares','saves','clicks','inquiries','qualified'].map(k=>field(k[0].toUpperCase()+k.slice(1),k,'','number','min="0" step="1"')).join('')+field('Reporting period & definition notes','notes','','textarea'),d=>api('metrics','POST',d));}
function adForm(){simpleForm('Prepare an advertising plan',`<div class="notice warning full">Planning only. Saving this form authorizes no advertising spend.</div>`+field('Plan name','name','','text','required')+select('Platform','platform','Facebook',P)+field('Campaign objective','objective')+field('Offering','offering')+field('Audience','audience')+field('Geography','geography')+field('Proposed ad account','account')+field('Landing page','landing','','url','required')+field('Creative concept','creative','','textarea')+field('Start date','start','','date','required')+field('End date','end','','date','required')+select('Currency','currency','USD',['USD','CAD','EUR','GBP'])+select('Budget type','budgetType','Lifetime',['Lifetime','Daily'])+field('Proposed spending limit','budget','','number','min="0" step="0.01" required')+field('Proposed spend alert threshold','alert','','number','min="0" step="0.01"')+select('Reviewer','reviewer','',teamOptions('Reviewer'))+select('Separate budget approver','approver','',teamOptions('Administrator'))+field('Success metric','metrics'),async d=>{if(d.end<d.start)throw Error('End date must follow start date.');await api('adPlans','POST',d);});}
function userForm(id){const u=state.users.find(u=>u.id===id)||{};simpleForm(id?'Manage team access':'Add an authenticated teammate',(id?'':field('Username','id','','text','required pattern="[a-z0-9_-]{3,40}"'))+field('Display name','name',u.name,'text','required')+field(id?'New password (leave blank to keep)':'Initial password (share privately)','password','','password',(id?'':'required ')+'minlength="14" autocomplete="new-password"')+`<div class="field full">Roles<div class="button-group">${['Administrator','Author','Reviewer','Publisher','Analyst'].map(r=>check(r,'role-'+r,u.roles?.includes(r))).join('')}</div></div><div class="field full">${check('Designated qualified technical safety reviewer','qualified',u.qualified)}${id?check('Disable access and revoke active sessions','disabled',u.disabled):''}</div>`,d=>api('users'+(id?'/'+id:''),id?'PUT':'POST',{...d,roles:['Administrator','Author','Reviewer','Publisher','Analyst'].filter(r=>d['role-'+r])}));}
function uploadForm(){simpleForm('Add to your asset library',`<label class="field full">Media file<input name="media" type="file" accept="image/png,image/jpeg,image/webp,video/mp4" required><small>10 MB maximum. Files stay on the server.</small></label>`+field('Asset name','name','','text','required')+field('Campaign tags','tags')+field('Description','description','','textarea')+field('Accessibility description','alt','','textarea')+field('Usage rights / permission record','rights','','textarea','required')+field('Permission expiration (optional)','expires','','date')+`<div class="field full">${check('Restricted: do not allow this asset to be used','restricted')}</div>`,async d=>{const file=$('[name=media]').files[0];if(file.size>10*1024*1024)throw Error('Maximum upload size is 10 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});delete d.media;await api('assets','POST',{...d,mime:file.type,data});});}
function brandForm(){const b=state.brand;simpleForm('Edit brand profile',field('Company name','name',b.name)+field('Website','website',b.website,'url','required')+field('Company description','description',b.description,'textarea')+field('Offerings','offerings',b.offerings,'textarea')+field('Geographic service area','geography',b.geography,'textarea')+field('Recommended writing style','style',b.style,'textarea')+field('Brand colors & verification notes','colors',b.colors,'textarea')+field('Verified phone (international format)','phone',b.phone)+field('Verified email','email',b.email,'email')+field('Messaging / social destination','dm',b.dm,'url')+field('Messaging verification source','dmSource',b.dmSource,'url')+field('Messaging verification date','dmVerifiedAt',b.dmVerifiedAt||'','date')+field('Uploaded logo path (optional)','logo',b.logo)+field('Contact source page','contactSource',b.contactSource,'url')+field('Contact verification date','contactVerifiedAt',b.contactVerifiedAt,'date')+`<div class="field full">${check('The phone and email were verified against the source above.','contactsVerified',b.contactsVerified)}${check('Messaging destination is verified against its source.','dmVerified',b.dmVerified)}${check('The correct website link is configured in our social bio.','bioConfirmed',b.bioConfirmed)}</div>`+field('Fact register (JSON; preserve source, date and verification labels)','facts',JSON.stringify(b.facts,null,2),'textarea')+`<div class="notice warning full">Saving brand changes invalidates existing content approvals so reviewers can confirm the new contact details.</div>`,async d=>{try{d.facts=JSON.parse(d.facts);if(!Array.isArray(d.facts))throw Error();}catch{throw Error('Fact register must be a JSON array.');}await api('brand','PUT',d);},true);}
function settingsForm(){const s=state.settings;simpleForm('Configure manual workspace',field('Calendar time zone (IANA)','zone',s.zone,'text','required')+`<div class="notice full">No social passwords or API tokens are requested here. These destinations are for manual posting. Requirement values are provisional until you review current official documentation.</div>`+P.map(p=>`<section class="field full account-config"><h3>${p}</h3><div class="form-grid">${field('Official account / composer URL','account-'+p,s.accounts[p].url,'url')}${field('Official requirements documentation','source-'+p,s.requirements[p].source,'url','required')}${field('Reviewed on','review-'+p,s.requirements[p].reviewedAt,'date')}${field('Caption character limit','limit-'+p,s.requirements[p].maxText,'number','min="1" required')}${field('Supported formats (comma separated)','formats-'+p,s.requirements[p].formats.join(', '))}${field('Maximum media assets (optional)','assets-'+p,s.requirements[p].maxAssets||'','number','min="1"')}${field('Maximum file bytes (optional)','bytes-'+p,s.requirements[p].maxMediaBytes||'','number','min="1"')}${field('Account eligibility / format limitations','notes-'+p,s.requirements[p].notes)}<div class="field full">${check('The team has verified this official destination.','verified-'+p,s.accounts[p].verified)}</div></div></section>`).join('')+`<div class="notice warning full">Saving destination or policy changes invalidates approvals. Automatic publishing and paid advertising cannot be enabled without implemented backend integrations.</div>`,async d=>{try{new Intl.DateTimeFormat('en',{timeZone:d.zone}).format();}catch{throw Error('Enter a valid IANA time zone.');}const accounts={},requirements={};P.forEach(p=>{accounts[p]={url:d['account-'+p],verified:d['verified-'+p]};requirements[p]={source:d['source-'+p],reviewedAt:d['review-'+p],maxText:Number(d['limit-'+p]),formats:d['formats-'+p].split(',').map(x=>x.trim()),maxAssets:Number(d['assets-'+p])||null,maxMediaBytes:Number(d['bytes-'+p])||null,notes:d['notes-'+p]};});await api('settings','PUT',{zone:d.zone,accounts,requirements});},true);}
function postEditor(id){
 const p=id?state.posts.find(p=>p.id===id):{title:'',platform:'LinkedIn',campaign:state.campaigns[0]?.id||'',audience:state.audiences[0]?.id||'',reviewer:teamOptions('Reviewer').find(([id])=>id!==state.user.id)?.[0]||teamOptions('Reviewer')[0]?.[0],publisher:teamOptions('Publisher')[0]?.[0],caption:'',format:'Text',cta:'Website',zone:state.settings.zone,planned:'',deadline:'',assetIds:[],status:'Draft',tone:'Professional',goal:'Awareness',length:'Short',version:1,history:[],comments:[]};
 const writable=can('Author','Administrator')&&p.status!=='Posted';
 openModal(id?'Content workspace':'Create a platform draft',`<div class="button-group">${platform(p.platform)}${badge(p.status)}<span class="badge">Manual publishing</span>${p.illustrative?'<span class="badge">Illustrative content</span>':''}</div><div class="editor-grid"><div><form id="post-form"><div class="form-grid"><div class="field full">${field('Post title','title',p.title,'text','required')}</div>${select('Platform','platform',p.platform,P)}${select('Format','format',p.format,['Text','Image','Video','Carousel'])}${select('Campaign','campaign',p.campaign,[['','No campaign'],...state.campaigns.map(c=>[c.id,c.name])])}${select('Audience','audience',p.audience,[['','No audience'],...state.audiences.map(a=>[a.id,a.name])])}${select('Tone','tone',p.tone,['Professional','Welcoming','Educational','Conversational'])}${select('Goal','goal',p.goal,['Awareness','Inquiries','Engagement','Training interest'])}${select('Length','length',p.length,['Short','Medium','Long'])}${select('Primary call to action','cta',p.cta,['Website','Call','Email','DM','Bio'])}${field('Caption','caption',p.caption,'textarea','required rows="7"')}<div class="button-group field full"><button type="button" class="small" id="add-cta">Insert CTA wording</button><button type="button" class="small" id="tracking">Build tracking link</button><span class="help" id="char-count">${p.caption.length} characters</span></div>${field('Slide copy / video hook, script, shot list & on-screen text','script',p.script,'textarea')}${field('Accessibility text','alt',p.alt,'textarea')}${field('Supporting sources & claim verification notes','claimSources',p.claimSources||state.brand.website,'textarea')}${select('Assigned reviewer','reviewer',p.reviewer,teamOptions('Reviewer'))}${select('Assigned publisher','publisher',p.publisher,teamOptions('Publisher'))}${field('Planned reminder (ISO with explicit offset)','planned',p.planned,'text','placeholder="2026-12-01T09:00:00-08:00"')}${field('Time zone for display (IANA)','zone',p.zone,'text','required')}${field('Review deadline (ISO with explicit offset)','deadline',p.deadline,'text','placeholder="2026-11-30T17:00:00-08:00"')}<div class="field full"><small>Enter Z or a UTC offset to disambiguate daylight-saving transitions. The calendar displays the resulting instant in the selected IANA time zone. Blank dates mean no reminder.</small></div><div class="field full">Media in posting order${state.assets.map(a=>check(esc(a.name)+' · '+esc(a.status)+(a.rights?'':' · permission missing'),'asset-'+a.id,p.assetIds?.includes(a.id))).join('')||'<span class="help">Upload an asset in the Asset library first.</span>'}<small>Assets follow library order. Download and upload them in the same order.</small></div><div class="field full">${check('I verified the facts and can substantiate every claim.','factsConfirmed',p.factsConfirmed)}${check('Contains technical safety guidance; requires qualified review.','technical',p.technical)}</div></div><div class="form-actions">${writable?'<button type="submit" class="primary">Save draft</button>':'<span class="help">Draft editing requires Author permission. Posted records are immutable.</span>'}</div></form><div class="section-title">Review & publication</div><div class="notice">Editing a saved draft invalidates approval. Each platform has independent content, states, dates and publication records.</div><div class="workflow">${id&&['Draft','Changes Requested'].includes(p.status)&&can('Author','Administrator')?'<button data-transition="In Review">Submit for review</button>':''}${p.status==='In Review'&&can('Reviewer')?'<button data-transition="Changes Requested">Request changes</button><button class="primary" data-transition="Approved">Approve content</button>':''}${p.status==='Approved'&&can('Publisher')?'<button class="primary" data-transition="Ready to Post">Mark ready to post</button>':''}${p.status==='Ready to Post'&&can('Publisher')?'<button class="primary" id="prepare">Prepare to Post ↗</button>':''}</div>${p.status==='In Review'&&can('Reviewer')?check('I am qualified and have reviewed the technical safety content.','technicalReviewed'):''}${p.publication?`<div class="notice"><b>Team-confirmed publication</b><br>${safeAnchor(p.publication.liveUrl,'Open live post')}<br>${esc(fmt(p.publication.actualAt,p.zone))} · ${esc(name(p.publication.publisher))}<br>${esc(p.publication.notes)}</div>`:''}${id?`<div class="section-title">Team comments</div><div class="history">${p.comments.map(c=>`<p><b>${esc(name(c.actor))}</b> · ${esc(fmt(c.at))}<br>${esc(c.text)}</p>`).join('')||'Start a review conversation.'}</div><form id="comment-form"><label class="field">Comment or requested revision<textarea name="text" required></textarea></label><button class="small" type="submit">Add comment</button></form><div class="section-title">Revision & approval history</div><div class="history">${p.history.slice().reverse().map(h=>`<p><b>${esc(h.action)}</b> · v${esc(h.version)}<br>${esc(name(h.actor))} · ${esc(fmt(h.at))}${h.caption?'<br>Previous caption: '+esc(h.caption):''}</p>`).join('')||'No revisions yet.'}</div>`:''}</div><aside class="editor-side"><div class="section-title">Platform preview · illustrative</div><div class="preview"><div class="preview-top"><span class="avatar">CS</span><div><b>CSTC Safety</b><small>${esc(p.platform)} preview · exact layout may vary</small></div></div>${p.assetIds?.map(id=>state.assets.find(a=>a.id===id)).filter(Boolean).map(a=>a.mime.startsWith('image/')?`<img src="/media/${a.file}" alt="${esc(p.alt||a.alt)}">`:`<video src="/media/${a.file}" controls></video>`).join('')||'<div class="preview-image">Your next conversation<br><small>Media preview appears after upload and save</small></div>'}<div class="preview-caption" id="preview-caption">${esc(p.caption||'Your caption will appear here.')}</div></div><section class="panel"><div class="panel-head"><h3>Pre-publication checks</h3></div><ul class="check-list">${id?[...state.checks[id].errors.map(t=>`<li class="error">${esc(t)}</li>`),...state.checks[id].warnings.map(t=>`<li>${esc(t)}</li>`)].join('')||'<li class="pass">Configured checks pass. Complete the final manual checklist.</li>':'<li>Save the draft to run server-side checks.</li>'}</ul></section><p class="help">Blocking errors must be resolved before preparation. Advisory warnings require judgment. Detailed media specifications require manual verification against current official documentation.</p></aside></div>`,true);
 currentPost=p;let dirty=false;
 if(!writable)$$('#post-form input,#post-form select,#post-form textarea,#post-form button').forEach(i=>i.disabled=true);
 $('#post-form').oninput=()=>{dirty=true;$('#preview-caption').textContent=$('[name=caption]').value;$('#char-count').textContent=$('[name=caption]').value.length+' characters';};
 $('#post-form').onsubmit=e=>{e.preventDefault();act(async()=>{const d=readForm(e.target);d.assetIds=state.assets.filter(a=>d['asset-'+a.id]).map(a=>a.id);for(const k of Object.keys(d))if(k.startsWith('asset-'))delete d[k];const result=await api('posts'+(id?'/'+id:''),id?'PUT':'POST',{...d,version:p.version,tracking:p.tracking});await refresh();postEditor(result.id);toast('Draft saved. Previous approvals require a fresh review.');});};
 $('#add-cta').onclick=()=>{const key=$('[name=cta]').value,b=state.brand,pl=$('[name=platform]').value;const wording={Website:['Facebook','LinkedIn'].includes(pl)?`Explore our services: ${b.website}`:'Visit CSTC Safety online or contact our team to learn more.',Call:b.contactsVerified?`Call CSTC: ${b.phone}`:'[Verify the company phone before posting]',Email:b.contactsVerified?`Email our team: ${b.email}`:'[Verify the company email before posting]',DM:b.dm&&b.dmVerified?'Message our team through our verified profile.':'[Configure a verified messaging destination]',Bio:b.bioConfirmed?'Visit the link in our bio.':'[Confirm the bio link before using this CTA]'}[key];$('[name=caption]').value+='\n\n'+wording;$('#post-form').dispatchEvent(new Event('input'));};
 $('#tracking').onclick=()=>trackingForm(p);
 $$('[data-transition]').forEach(b=>b.onclick=()=>act(async()=>{if(dirty)throw Error('Save draft changes before taking a review or publishing action.');await api('posts/'+id+'/transition','POST',{status:b.dataset.transition,version:p.version,technicalReviewed:$('[name=technicalReviewed]')?.checked||false});await refresh();postEditor(id);toast('Status updated.');}));
 if($('#comment-form'))$('#comment-form').onsubmit=e=>{e.preventDefault();act(async()=>{if(dirty)throw Error('Save draft changes before adding a comment.');await api('posts/'+id+'/comment','POST',readForm(e.target));await refresh();postEditor(id);});};
 if($('#prepare'))$('#prepare').onclick=()=>{if(dirty)return toast('Save your changes before preparing.');return act(()=>preparePost(p));};
}
function trackingForm(post){const c=state.campaigns.find(c=>c.id===post.campaign);const form=document.createElement('div');form.id='tracking-inline';form.className='notice';form.innerHTML=`<h3>Campaign tracking link</h3><div class="form-grid">${field('Destination','utm-destination',state.brand.website,'url')}${field('Source','utm-source',post.platform.toLowerCase())}${field('Medium','utm-medium','organic_social')}${field('Campaign','utm-campaign',c?.utmCampaign||'campaign')}${field('Content identifier (no personal information)','utm-content',post.id||'draft')}</div><p class="help">Existing query parameters are preserved. No personal information in tracking parameters. A tagged link alone does not establish a conversion; analytics or another configured source is required.</p><button type="button" id="insert-utm" class="small">Insert tracking link</button><button type="button" id="cancel-utm" class="ghost small">Close</button>`;$('#tracking-inline')?.remove();$('#tracking').closest('.field').after(form);$('#cancel-utm').onclick=()=>form.remove();$('#insert-utm').onclick=()=>act(async()=>{const u=new URL($('[name=utm-destination]').value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('Use a valid HTTP or HTTPS destination.');const params={};['source','medium','campaign','content'].forEach(k=>{const v=$('[name=utm-'+k+']').value.trim();if(/[@\s]/.test(v))throw Error('Use consistent names without spaces or personal information.');if(v){u.searchParams.set('utm_'+k,v);params['utm_'+k]=v;}});post.tracking={destination:u.href,parameters:params,createdAt:new Date().toISOString()};$('[name=caption]').value+='\n\n'+u.href;$('#post-form').dispatchEvent(new Event('input'));toast('Link inserted. Save the draft to record it.');form.remove();});}
async function preparePost(p){const checked=await api('posts/'+p.id+'/prepare');p=checked.post;const b=state.brand,a=state.settings.accounts[p.platform];const instructions={Instagram:'Open Instagram. Choose the correct account and create the selected post or reel. Add media in the listed order, paste the approved caption, and add accessibility text. Confirm bio links separately.',TikTok:'Open TikTok. Select the verified account. Upload the approved video, check sound and on-screen text, paste the caption, and add accessibility information.',Facebook:'Open the verified Facebook Page. Create the post, attach the ordered media, paste the caption and website link, and check the preview.',LinkedIn:'Open the verified LinkedIn account or company Page. Start a post, add media in order, paste the caption and link, add accessibility text, and review the audience.'}[p.platform];openModal('Prepare to Post · '+esc(p.platform),`<div class="notice"><b>This is manual posting.</b> A teammate publishes directly on ${esc(p.platform)}. The app cannot verify the platform result.</div><div class="editor-grid"><div><h3>${esc(p.title)}</h3><div class="monospace">${esc(p.caption)}</div><div class="button-group toggle-note"><button id="copy-caption">Copy approved caption</button>${a.verified?safeAnchor(a.url,'Open verified platform destination'):''}</div><div class="section-title">Media · upload in this order</div>${p.assetIds.map((id,i)=>{const a=state.assets.find(a=>a.id===id);return `<p class="help">${i+1}. ${esc(a.name)} <a href="/media/${a.file}" download>Download</a><br>Accessibility: ${esc(p.alt||a.alt||'Not supplied')}</p>`;}).join('')||'<p class="help">Text-only post. No media attached.</p>'}<div class="section-title">Posting instructions</div><p class="help">${instructions}</p><p class="help"><b>Verified contacts:</b> ${esc(b.phone)} · ${esc(b.email)}<br>${safeAnchor(b.website,'Visit CSTC Safety')}<br>Source: ${safeAnchor(b.contactSource,'Contact page')} · ${esc(b.contactVerifiedAt)}</p></div><div><h3>Final manual checklist</h3><form id="publication-form">${['I checked the correct account and audience.','I checked caption, media order, accessibility and rights.','I checked current platform media size, duration, dimensions and format.','I opened and checked each destination link.','I published the approved content on the platform.'].map((t,i)=>`<label class="check-field"><input type="checkbox" required name="final-${i}">${t}</label>`).join('')}<div class="section-title">Record the result afterward</div><div class="form-grid">${field('Live post URL','liveUrl','','url','required')}${field('Actual publication time (ISO with offset)','actualAt',new Date().toISOString(),'text','required')}${field('Optional publication notes','notes','','textarea')}</div><p class="help">Publishing teammate: ${esc(state.user.name)}. Records a <b>Team-confirmed publication</b>, not platform confirmation.</p><button type="submit" class="primary">Record team-confirmed publication</button></form></div></div>`,true);$('#copy-caption').onclick=()=>copy(p.caption);$('#publication-form').onsubmit=e=>{e.preventDefault();act(async()=>{await api('posts/'+p.id+'/transition','POST',{...readForm(e.target),status:'Posted',version:p.version});closeModal();await refresh();toast('Team-confirmed publication recorded for '+p.platform+'.');});};}
function repurpose(campaignId){simpleForm('Turn one idea into platform drafts',`<div class="notice full">Template-based drafting. No AI is connected. Each destination gets its own draft and review.</div>`+select('Campaign','campaign',campaignId||state.campaigns[0]?.id,state.campaigns.map(c=>[c.id,c.name]))+select('Template','template','Service spotlight',['Service spotlight','Training promotion','Educational series','Frequently asked questions','Company introduction'])+field('Core idea / topic','idea','','text','required')+`<div class="field full">${P.map(p=>check(p,'platform-'+p,true)).join('')}</div><div class="field full">${check('I confirm the campaign offering is relevant. All resulting content will be verified before approval.','confirm')}</div>`,async d=>{if(!d.confirm)throw Error('Confirm the campaign offering first.');const c=state.campaigns.find(c=>c.id===d.campaign);if(!c?.offeringConfirmed)throw Error('Create and confirm a campaign offering first.');const chosen=P.filter(p=>d['platform-'+p]);if(!chosen.length)throw Error('Select at least one platform.');for(const p of chosen){const captions={LinkedIn:`${d.idea}\n\nEvery workplace has its own training needs. Explore CSTC’s ${c.offering.toLowerCase()} and start a conversation about your team.\n\n${state.brand.website}`,Facebook:`What would your team like to know about ${c.offering.toLowerCase()}?\n\n${d.idea}\n\nExplore CSTC’s services: ${state.brand.website}`,Instagram:`${d.idea}\n\nLet’s start a conversation about ${c.offering.toLowerCase()}. Contact CSTC to explore your options.\n\n#SafetyTraining #TeamLearning`,TikTok:`${d.idea}\n\nWhat would you ask about ${c.offering.toLowerCase()}? Contact CSTC to learn more.`};await api('posts','POST',{title:d.idea,platform:p,campaign:c.id,audience:c.audience,reviewer:c.reviewer,publisher:c.publisher,caption:captions[p],format:p==='TikTok'?'Video':p==='Instagram'?'Image':'Text',cta:'Website',zone:state.settings.zone,planned:'',deadline:'',alt:'',assetIds:[],factsConfirmed:false,technical:d.template==='Educational series',script:p==='TikTok'?`Hook: ${d.idea}\nShot 1: Presenter asks a question.\nOn-screen text: ${c.offering}\nShot 2: Introduce the verified service without technical instructions.\nClosing CTA: Contact CSTC.`:p==='Instagram'?`Slide 1: ${d.idea}\nSlide 2: Introduce ${c.offering}.\nSlide 3: Invite questions.\nStory: Question sticker about training needs.\nReel: Introduce the topic, show permission-cleared footage, invite a question.`:'Discussion prompt: What questions would help your team plan?',tone:'Professional',goal:c.objective,length:'Short',illustrative:true,template:d.template});}},true);}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Copied to clipboard.');}catch{toast('Clipboard unavailable. Select and copy the displayed text.');}}
function exportCsv(rows,filename){if(!rows.length)return toast('No records available to export.');const keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>!['password','token'].includes(k));const cell=v=>{let s=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv=[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function start(){try{boot=await api('bootstrap');if(boot.user){await refresh();clearInterval(refreshTimer);refreshTimer=setInterval(async()=>{if(!$('.modal')){try{await refresh();}catch{}}},60000);return;}$('#app').innerHTML=`<main class="login"><section class="card"><div class="brandmark"><div class="mark">✧</div><div><strong>CSTC</strong><small>SOCIAL STUDIO</small></div></div><h1>A space for safer conversations.</h1><p class="help">Plan, create, review and prepare your team’s social content.</p>${boot.demo?'<div class="notice">Demonstration mode. Identity selection is simulated. Data is persisted on this server. Sample campaigns are illustrative.</div>':''}<form id="login-form">${boot.demo?select('Simulated teammate','id','admin',boot.users.map(u=>[u.id,u.name+' · '+u.roles.join(', ')])):field('Username','id','','text','required autocomplete="username"')}${boot.demo?'':field('Password','password','','password','required autocomplete="current-password"')}<button class="primary" type="submit">${boot.demo?'Open demonstration':'Sign in'} ${icon('arrow',14)}</button></form><p class="help"><a href="https://www.cstcsafety.com/" target="_blank" rel="noopener">Visit CSTC Safety ↗</a></p></section></main>`;$('#login-form').onsubmit=e=>{e.preventDefault();act(async()=>{await api('session','POST',readForm(e.target));await start();});};}catch(e){$('#app').innerHTML=`<main class="login"><section class="card"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><p class="help">Check that the server is running and reload this page.</p></section></main>`;}}
start();

function assetForm(id){const a=state.assets.find(a=>a.id===id);simpleForm('Edit asset permissions',field('Name','name',a.name,'text','required')+field('Tags','tags',a.tags)+field('Description','description',a.description,'textarea')+field('Accessibility text','alt',a.alt,'textarea')+field('Permission record','rights',a.rights,'textarea')+field('Expiration','expires',a.expires,'date')+`<div class="field full">${check('Restricted — block from use','restricted',a.restricted)}</div><div class="notice warning full">Changes reset asset approval and invalidate approval for every affected draft.</div>`,d=>api('assets/'+id,'PUT',d));}

function simulationModal(){openModal('Publishing queue · simulation only',`<div class="notice warning"><b>No platform calls. No posts are published.</b> This manually stepped demonstration stores jobs in SQLite and exercises duplicate prevention, pause, cancellation, failure and uncertain-outcome reconciliation. A simulated confirmation never changes a post to Published.</div><p class="help">Current control: <b>${state.settings.paused?'PAUSED':'Simulation steps allowed'}</b>. Live automatic publishing remains disabled.</p><div class="button-group">${can('Administrator')?`<button id="sim-toggle">${state.settings.paused?'Allow simulation steps':'Pause simulation steps'}</button>`:''}</div><div class="section-title">Queue an approved draft</div><form id="sim-enqueue"><div class="form-grid">${select('Approved post','postId','',state.posts.filter(p=>p.status==='Approved').map(p=>[p.id,p.title+' · '+p.platform]))}${field('Simulation due time (ISO with offset)','dueAt',new Date().toISOString(),'text','required')}</div><p class="help">Requires an approved draft, verified destination and passing content checks. The same content version produces the same job.</p>${can('Publisher')?'<button type="submit" class="primary">Queue simulated job</button>':''}</form><div class="section-title">Durable simulation jobs</div>${(state.jobs||[]).slice().reverse().map(j=>`<div class="account-config"><h3>${esc(state.posts.find(p=>p.id===j.postId)?.title||j.postId)}</h3><p class="help">${esc(j.platform)} · v${j.version} · ${esc(j.mode)}<br>Due: ${esc(fmt(j.dueAt))}<br>State: <b>${esc(j.status)}</b> · Attempts: ${j.attempts}<br>${esc(j.reason||'')}${j.simulatedId?'<br>Simulated ID: '+esc(j.simulatedId):''}</p>${can('Publisher')?`<div class="button-group">${j.status==='Queued'?`<button data-sim="step" data-job="${j.id}">Start simulated attempt</button>`:''}${j.status==='Processing'?`<button data-sim="step" data-outcome="confirmed" data-job="${j.id}">Simulate confirmation</button><button data-sim="step" data-outcome="failed" data-job="${j.id}">Simulate rejection</button><button data-sim="step" data-outcome="uncertain" data-job="${j.id}">Simulate uncertainty</button>`:''}${j.status==='Uncertain'?`<button data-sim="reconcile" data-outcome="created" data-job="${j.id}">Reconcile: created</button><button data-sim="reconcile" data-outcome="not-created" data-job="${j.id}">Reconcile: not created</button>`:''}${j.status==='Failed'?`<button data-sim="retry" data-job="${j.id}">Retry same job safely</button>`:''}${!['Cancelled','Simulated confirmation'].includes(j.status)?`<button data-sim="cancel" data-job="${j.id}">Cancel simulated job</button>`:''}</div>`:''}</div>`).join('')||'<p class="help">No simulation jobs. Approve a draft to explore the queue.</p>'}`,true);if($('#sim-toggle'))$('#sim-toggle').onclick=()=>act(async()=>{await api('settings','PUT',{paused:!state.settings.paused});await refresh();simulationModal();});$('#sim-enqueue').onsubmit=e=>{e.preventDefault();act(async()=>{await api('publishing-simulation','POST',{...readForm(e.target),action:'enqueue'});await refresh();simulationModal();});};$$('[data-sim]').forEach(b=>b.onclick=()=>act(async()=>{await api('publishing-simulation','POST',{action:b.dataset.sim,id:b.dataset.job,outcome:b.dataset.outcome});await refresh();simulationModal();}));}
